// maxpool2x2.v
// ------------------------------------------------------------
// 2x2 max pooling over 4 signed inputs.
//
// Given four inputs from a 2x2 window, produces the maximum:
//
//   a00 a01        output = max(a00, a01, a10, a11)
//   a10 a11
//
// In LeNet-5 this module is used twice:
//   - pool1 : 28x28 -> 14x14 after conv1
//   - pool2 : 10x10 -> 5x5   after conv2
//
// The caller (feature_buffer / top FSM) is responsible for
// fetching the four correct values from the feature map.
// This module is stateless: same inputs always produce same
// output, no clock required.
//
// Implementation: pure combinational.
//   Three comparators arranged in a 2-level reduction tree.
//   Written as explicit stages for clarity; synthesis tools
//   realize it as a balanced tree in 1 cycle of gate delay.
//
// Parameter:
//   WIDTH - bit width of each input and the output (default 8)
// ============================================================

`timescale 1ns / 1ps

module maxpool2x2 #(
    parameter integer WIDTH = 8
)(
    input  wire signed [WIDTH-1:0] a00,
    input  wire signed [WIDTH-1:0] a01,
    input  wire signed [WIDTH-1:0] a10,
    input  wire signed [WIDTH-1:0] a11,
    output wire signed [WIDTH-1:0] dout
);

    // Stage 1: pairwise max along the top row and bottom row
    wire signed [WIDTH-1:0] top_max;
    wire signed [WIDTH-1:0] bot_max;

    assign top_max = (a01 > a00) ? a01 : a00;
    assign bot_max = (a11 > a10) ? a11 : a10;

    // Stage 2: max of the two row-maxes
    assign dout = (bot_max > top_max) ? bot_max : top_max;

endmodule
